#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;

int mod;
inline int add_mod(int x) {
    return x >= mod ? x - mod : x;
}
inline int sub_mod(int x) {
    return x < 0 ? x + mod : x;
}
int fast_pow(int base, int exp) {
    int result = 1;
    while (exp > 0) {
        if (exp & 1) result = (long long)result * base % mod;
        base = (long long)base * base % mod;
        exp >>= 1;
    }
    return result;
}
struct Point {
    int f, g;
    Point(int f=0, int g=0):f(f), g(g) {}
};
Point operator+(const Point &a, const Point &b) {
    return Point(add_mod(a.f + b.f), add_mod(a.g + b.g));
}
Point operator*(const Point &a, const Point &b) {
    return Point((long long)a.f * b.f % mod, add_mod((long long)a.f * b.g % mod + (long long)a.g * b.f % mod));
}
int n, m, maxN=100000;
int factorial[100005], inv_factorial[100005], inv_num[100005];
Point dp[1005], prefix[1005][1005];

int sum_formula(int x) {
    return (long long)x * (x + 1) / 2 % mod;
}

int main() {
    scanf("%d%d%d", &n, &m, &mod);
    factorial[0] = inv_factorial[0] = 1;
    for (int i=1; i<=maxN; i++) {
        factorial[i] = (long long)i * factorial[i-1] % mod;
        inv_factorial[i] = fast_pow(factorial[i], mod - 2);
        inv_num[i] = fast_pow(i, mod - 2);
    }
    dp[0] = Point(1, 0);
    for (int i=1; i<=n; i++) {
        for (int j=1; j<=i; j++) {
            Point temp = dp[j-1] * dp[i-j];
            temp.g = add_mod((long long)temp.g * (i+1) % mod + (long long)temp.f * add_mod(sum_formula(j-1) + sum_formula(i-j)) % mod);
            temp.g = (long long)temp.g * inv_num[i] % mod;
            temp.f = (long long)temp.f * (i+1) % mod * inv_num[i] % mod;
            dp[i] = dp[i] + temp;
        }
    }
    prefix[0][0] = Point(1, 0);
    for (int i=1; i<=n; i++) {
        for (int j=0; j<=std::min(i, m); j++) {
            if (i == j) prefix[i][j] = dp[i];
            for (int k=0; k<j && k<i; k++) {
                prefix[i][j] = prefix[i][j] + dp[k] * prefix[i - k - 1][j - k];
            }
        }
    }
    int answer = (long long)prefix[n][m].g * factorial[m] % mod;
    printf("%d\n", answer);
    return 0;
}
